var t=`0302-trilece`;var n=`world-0302`;var a=`AL`;var r=`southern-europe`;var l=8;var o=211;var s={en:`Trileçe`,ua:`Трилече`};var d={en:`A home-kitchen tres-leches-style cake assembled using brioche because prepared sponge cake is absent from the ingredient catalog.`,ua:`Домашній варіант десерту «три молока» на основі бріоші, оскільки готового бісквіта в каталозі немає.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`whole-cow-milk`,650,`ml`],[`chicken-egg`,4,`pcs`],[`white-granulated-sugar`,170,`g`],[`vanilla-extract`,5,`ml`]]},{en:`Arrange slices of brioche in a deep dish and slowly pour over the mixed sweetened condensed, evaporated and whole milk with cream, letting the bread soak evenly.`,ua:`Викладіть скибочки бріоші в глибоку форму та повільно залийте сумішшю згущеного, пряженого молока й вершків, щоб хліб рівномірно просочився.`,t:[`layered-assembly`],m:13,i:[[`brioche`,420,`g`],[`sweetened-condensed-milk`,250,`g`],[`evaporated-milk`,330,`ml`],[`heavy-cream`,220,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 180 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 180 хвилин.`,t:[`rapid-chilling`],m:180,i:[]},{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 11 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 11 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:11,i:[[`white-granulated-sugar`,120,`g`],[`water`,40,`ml`]]}];var g={slug:t,id:n,country:`AL`,region:r,servings:8,minutes:211,title:s,text:d,steps:m};export{a as country,g as default,n as id,o as minutes,r as region,l as servings,t as slug,m as steps,d as text,s as title};